<?php
declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('wallet.view');
$q=trim((string)input('q'));$type=strtoupper((string)input('type'));$from=trim((string)input('from'));$to=trim((string)input('to'));$page=page_int();[$limit,$offset]=pagination($page);$where=[];$params=[];
if($q!==''){$where[]='(t.transaction_id LIKE ? OR u.name LIKE ? OR u.mobile LIKE ? OR u.email LIKE ? OR t.reference LIKE ?)';$params=array_fill(0,5,'%'.$q.'%');}if(in_array($type,['CREDIT','DEBIT','WITHDRAWAL','REFUND','ADJUSTMENT','REVERSAL','BONUS_CREDIT','BONUS_DEBIT','PROMO_CREDIT','PROMO_DEBIT','CHECKOUT','PROMO_REVERSAL'],true)){$where[]='t.type=?';$params[]=$type;}if($from!==''&&valid_date($from)){$where[]='t.created_at>=?';$params[]=$from;}if($to!==''&&valid_date($to)){$where[]='t.created_at<DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$to;}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';
$count=db()->prepare('SELECT COUNT(*) FROM wallet_transactions t JOIN users u ON u.id=t.user_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT t.*,u.name,u.mobile,u.email FROM wallet_transactions t JOIN users u ON u.id=t.user_id'.$sqlWhere.' ORDER BY t.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();$pageTitle='Wallet ledger';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><div class="panel-head"><h2>Transactions</h2><?php if(can('wallet.credit')||can('wallet.debit')):?><a class="btn" href="<?=e(app_url('/admin/wallets/adjust.php'))?>">New adjustment</a><?php endif?></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="User ID, mobile, transaction or reference"><select name="type"><option value="">All Users / types</option><?php foreach(['CREDIT','DEBIT','WITHDRAWAL','REFUND','ADJUSTMENT','REVERSAL','BONUS_CREDIT','BONUS_DEBIT','PROMO_CREDIT','PROMO_DEBIT','CHECKOUT','PROMO_REVERSAL'] as $s):?><option <?=$type===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Txn ID</th><th>User ID</th><th>Customer / phone</th><th>Target pocket</th><th>Real cash</th><th>Bonus amount</th><th>Type</th><th>Transaction event</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php $bonus=in_array($r['bucket'],['BONUS','PROMO'],true); ?><td><strong><?=e($r['transaction_id'])?></strong></td><td>USR_<?=e((string)$r['user_id'])?></td><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['mobile']??'—')?></small></td><td><?=e($r['bucket'])?></td><td><?= $bonus?'₹0.00':money($r['amount'])?></td><td><?= $bonus?money($r['amount']):'₹0.00'?></td><td><?=e($r['type'])?></td><td><?=e($r['description']??$r['reference']??'—')?></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><a class="btn small secondary" href="<?=e(app_url('/admin/wallets/customer.php?id='.$r['user_id']))?>">👁 View customer</a></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No transactions found.</div><?php endif?></div><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><a href="?<?=e(http_build_query(['q'=>$q,'type'=>$type,'from'=>$from,'to'=>$to,'page'=>$i]))?>"><?=$i?></a><?php endfor?></div></section><?php require APP_ROOT.'/includes/footer.php';

